      prismP(B.p(BR), P, gs + 0.5, gs + eav); winsP(B.p(SG), P, gs + 1.5, gs + eav - 0.6, 6, 3.0, 1.0, Math.min(3.0, eav - 2.2), 0.05);
      winsP(B.p(GR), P, gs + 1.35, gs + eav - 0.45, 6, 3.0, 1.3, 0.12, 0.07);
